  >
>
type Callback<E extends Env, P extends string, O, R> = (
  c: Context<E, P, RequestInput<O>>,
  input: RequestInput<O>['out']
) => R

type Allowed<O> = 'response' extends keyof O ? SchemaInput<O['response']> | Response : unknown

